#include "sys_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void sys_timer_register (Timer_Timer_Func timer_func , UInt32 timeout)
{
  CRITICAL ;

  C_ENTER ;
    {
      add_to_list :
        {
          Timer_Entry * timer_entry = (Timer_Entry *) os_mem_request (sizeof (Timer_Entry)) ;
    
          timer_entry -> timer_func = timer_func    ;
          timer_entry -> next       = timer_list    ;
    
          timer_entry -> timeout          = 1       ;
          timer_entry -> timeout_assigned = timeout ;
    
          timer_list = timer_entry ;
        }
    }
  C_LEAVE ;
}


